begin;
select no_plan();
select ok(not has_function_privilege('authenticated','api.execute_owner_profile_editor_server(uuid,text,jsonb)','EXECUTE'),'Browser cannot spoof gateway subject');
select ok(not has_function_privilege('anon','api.execute_owner_profile_editor_server(uuid,text,jsonb)','EXECUTE'),'Anonymous cannot call layout gateway');
select ok(has_function_privilege('service_role','api.execute_owner_profile_editor_server(uuid,text,jsonb)','EXECUTE'),'Server gateway available');
insert into auth.users(id,email) values('26400000-0000-4000-8000-000000000001','create-link-gateway-one@example.test'),('26400000-0000-4000-8000-000000000002','create-link-gateway-two@example.test');
create temporary table actors as select auth_user_id,owner_id from core.owner_auth_bindings where auth_user_id in('26400000-0000-4000-8000-000000000001','26400000-0000-4000-8000-000000000002');
update core.owner_onboarding_progress set current_step='preview_publish',primary_use_case='personal' where owner_id in(select owner_id from actors);
insert into core.owner_handle_namespaces(normalized_handle,owner_id,namespace_kind) select 'create264-'||right(auth_user_id::text,6),owner_id,'current' from actors;
update core.owners set onboarding_completed_at=now() where id in(select owner_id from actors);
insert into core.identity_working(owner_id,display_name,bio,revision) select owner_id,'Source Profile','Retained Bio',2 from actors;
insert into core.identity_layout_working(owner_id,starter_key,revision) select owner_id,'clean',1 from actors;
insert into core.identity_publications(owner_id,snapshot,identity_revision,layout_revision,connection_revision,published_at) select owner_id,'{"legacy":true}',2,1,null,now() from actors;
select ok(not has_function_privilege('service_role','api.initialize_current_owner_blocks_from_link(jsonb)','EXECUTE'),'Original first initializer remains withheld');
select ok(not has_function_privilege('service_role','api.add_current_owner_link_block_working(jsonb)','EXECUTE'),'Original append remains withheld');
create temporary table created(result jsonb);
grant select,insert on created to service_role;
create function pg_temp.allocate_link(subject uuid,base bigint,kind text) returns jsonb language sql as $$select api.execute_owner_profile_editor_server(subject,case when base is null then 'initialize_current_owner_blocks_from_link' else 'add_current_owner_link_block_working' end,jsonb_build_object('input_intent',jsonb_build_object('action',case when base is null then 'initialize_link_block' else 'add_link_block' end,'base_collection_revision',base,'is_visible',false,'link_working',jsonb_build_object('kind',kind,'title',' Raw <title> ','social_platform',null,'destination_url','javascript:unfinished'))));$$;
grant execute on function pg_temp.allocate_link(uuid,bigint,text) to service_role;
set local request.jwt.claims='{"role":"service_role","sub":"26400000-0000-4000-8000-000000000002"}';
set local request.jwt.claim.sub='26400000-0000-4000-8000-000000000002';
set local role service_role;
insert into created select pg_temp.allocate_link('26400000-0000-4000-8000-000000000001',null,'generic_link');
select is((select result->>'status' from created),'success','Actual service gateway explicitly initializes without source');
select is((select result->>'collection_revision' from created),'1','First exact creation revision');
select is(current_setting('request.jwt.claim.sub'),'26400000-0000-4000-8000-000000000002','First allocation restores subject');
select is(pg_temp.allocate_link('26400000-0000-4000-8000-000000000001',null,'generic_link')->>'status','already_initialized','Repeated absence intent cannot duplicate');
insert into created select pg_temp.allocate_link('26400000-0000-4000-8000-000000000001',1,'social');
select is((select result->>'collection_revision' from created where result->>'collection_revision'='2'),'2','Append exact next revision');
select is(pg_temp.allocate_link('26400000-0000-4000-8000-000000000001',1,'social')->>'status','stale_write','Old append base cannot duplicate');
select is(api.execute_owner_profile_editor_server('26400000-0000-4000-8000-000000000001','initialize_current_owner_blocks_from_link','{"input_intent":{},"owner_id":"26400000-0000-4000-8000-000000000002"}')->>'status','unavailable','Closed initializer envelope denies caller Owner');
select is(api.execute_owner_profile_editor_server('26400000-0000-4000-8000-000000000001','add_current_owner_link_block_working','{"input_working":{}}')->>'status','unavailable','Wrong append envelope denied');
reset role;
select is((select count(*)::int from core.identity_blocks_working where owner_id=(select owner_id from actors where auth_user_id='26400000-0000-4000-8000-000000000001')),2,'Exactly two own members');
select is((select count(distinct result->>'block_id')::int from created),2,'Distinct server IDs');
select ok(not exists(select 1 from core.identity_blocks_working where owner_id=(select owner_id from actors where auth_user_id='26400000-0000-4000-8000-000000000001') and is_visible),'Explicit hidden Working retained');
select ok(not exists(select 1 from core.identity_block_links_working where owner_id=(select owner_id from actors where auth_user_id='26400000-0000-4000-8000-000000000001') and (title<>' Raw <title> ' or destination_url<>'javascript:unfinished')),'Unfinished raw fields persisted exactly');
select is((select count(*)::int from core.identity_block_collections_working where owner_id=(select owner_id from actors where auth_user_id='26400000-0000-4000-8000-000000000002')),0,'Foreign Owner unaffected by first Owner allocation');
insert into core.identity_block_collections_working(owner_id,revision) select owner_id,5 from actors where auth_user_id='26400000-0000-4000-8000-000000000002';
set local role service_role;
select is(pg_temp.allocate_link('26400000-0000-4000-8000-000000000002',5,'generic_link')->>'collection_revision','6','Existing empty collection appends rather than recreates');
select is(pg_temp.allocate_link('26400000-0000-4000-8000-000000000002',null,'social')->>'status','already_initialized','Existing collection never overwritten');
reset role;
select ok(not exists(select 1 from core.identity_publications where snapshot<>'{"legacy":true}'::jsonb),'Published snapshots untouched');
select ok(not exists(select 1 from core.identity_working where owner_id in(select owner_id from actors) and (display_name<>'Source Profile' or revision<>2)),'Profile source preserved');
select ok(not exists(select 1 from core.identity_connection_working where owner_id in(select owner_id from actors)),'No automatic source Connection');
create function pg_temp.reject_member_insert() returns trigger language plpgsql as $$begin raise exception 'fixture member write failure';end;$$;
create trigger create_link_editor_fixture before insert on core.identity_blocks_working for each row execute function pg_temp.reject_member_insert();
set local role service_role;
select throws_ok($q$select pg_temp.allocate_link('26400000-0000-4000-8000-000000000001',2,'social')$q$,'P0001','fixture member write failure','Partial allocation rolls back on exception');
select is(current_setting('request.jwt.claims')::jsonb,'{"role":"service_role","sub":"26400000-0000-4000-8000-000000000002"}'::jsonb,'Exception restores complete caller claims');
reset role;
drop trigger create_link_editor_fixture on core.identity_blocks_working;
select is((select revision::text from core.identity_block_collections_working where owner_id=(select owner_id from actors where auth_user_id='26400000-0000-4000-8000-000000000001')),'2','Failed allocation did not advance base');
update core.owners set account_state='restricted' where id in(select owner_id from actors);
set local role service_role;
select is(pg_temp.allocate_link('26400000-0000-4000-8000-000000000001',2,'social')->>'status','owner_not_eligible','Restriction denies creation');
reset role;
select * from finish();
rollback;
